import type { CropDetail, CropResult, RecommendResponse } from "../lib/types";
import scaleRules from "./scale-rules.json";
import marianna from "./marianna.json";
import hastings from "./hastings.json";
import plantCity from "./plant_city.json";
import belleGlade from "./belle_glade.json";

interface DemoSample {
  recommend: RecommendResponse;
  crops: Record<string, CropDetail>;
}

// Generated JSON widens literal strings; the generator supplies contract values.
const samples = [marianna, hastings, plantCity, belleGlade] as DemoSample[];
// Generated by backend/scripts/export_scale_rules.py from the normal scorer.
const rules = scaleRules as Record<string, { below: number; scale: CropResult["scale"]; cap: number }[]>;

function applyAcreage(crop: CropResult, acres?: number): CropResult {
  if (acres === undefined) return crop;
  if (!Number.isFinite(acres) || acres < 0.1 || acres > 10000) {
    throw new Error("Acreage must be between 0.1 and 10000");
  }
  const band = rules[crop.id ?? ""]?.find((entry) => acres < entry.below);
  if (!band) throw new Error("Saved acreage rules are unavailable for this crop");
  const scale = { ...band.scale, note: band.scale.note?.replace("{acres}", String(acres)) ?? null };
  const flags = (crop.flags ?? []).filter((flag) => flag !== crop.scale?.note);
  return { ...crop, scale, score: crop.score === null ? null : Math.min(crop.score, band.cap),
    flags: (scale.note ? [scale.note, ...flags] : flags).slice(0, 4),
    // Saved commercial averages do not establish returns for this lot.
    est_gross_value: null };
}

function savedProvenance(response: RecommendResponse): void {
  response.warnings = ["Saved demo data for the nearest Florida demo farm; soil and climate are not live measurements for your property.",
    ...(response.warnings ?? [])];
  response.provenance = { mode: "demo", fawn_station: response.provenance?.fawn_station ?? null,
    sources: (response.provenance?.sources ?? []).map((source) => ({ ...source, status: "saved" })) };
}
const demos = samples.map((sample) => sample.recommend);

/** Great-circle distance term; sufficient for comparing demo locations. */
function distance(lat: number, lon: number, demoLat: number, demoLon: number): number {
  const radians = Math.PI / 180;
  return Math.sin((demoLat - lat) * radians / 2) ** 2
    + Math.cos(lat * radians) * Math.cos(demoLat * radians)
    * Math.sin((demoLon - lon) * radians / 2) ** 2;
}

/** Real backend samples. Return independent copies to protect shared fixtures. */
export function getMockRecommend(lat: number, lon: number, acres?: number): RecommendResponse {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    throw new Error("Latitude and longitude must be finite numbers");
  }
  let nearest = demos[0];
  let nearestDistance = Infinity;
  for (const demo of demos) {
    const candidate = distance(lat, lon, demo.location?.lat ?? NaN, demo.location?.lon ?? NaN);
    if (candidate < nearestDistance) {
      nearest = demo;
      nearestDistance = candidate;
    }
  }
  const result = structuredClone(nearest);
  result.crops = (result.crops ?? []).map((crop) => applyAcreage(crop, acres))
    .sort((a, b) => (b.score ?? -1) - (a.score ?? -1) || (a.name ?? "").localeCompare(b.name ?? ""));
  savedProvenance(result);
  return result;
}

export function getMockCropDetail(id: string, lat: number, lon: number, acres?: number): CropDetail {
  const nearest = getMockRecommend(lat, lon);
  const sample = samples.find((candidate) => candidate.recommend.location?.lat === nearest.location?.lat
    && candidate.recommend.location?.lon === nearest.location?.lon);
  const detail = sample?.crops[id];
  if (!detail) throw new Error("Unknown crop");
  const result = structuredClone(detail);
  const adjusted = getMockRecommend(lat, lon, acres);
  const scored = adjusted.crops?.find((crop) => crop.id === id);
  if (scored) Object.assign(result, scored);
  result.provenance = adjusted.provenance;
  return result;
}
